/// <reference path="../../index.d.ts" />
import type { PublicLitElement as LitElement } from "@arcgis/lumina";
import type { IconName } from "../calcite-icon/types.js";

declare module "@arcgis/lumina" {
export interface DeclareCssProperties {
  /** Specifies the component's color. */
  "--calcite-segmented-control-color": "*";
  /** Specifies the component's background color. */
  "--calcite-segmented-control-background-color": "*";
  /** Specifies the component's shadow. */
  "--calcite-segmented-control-shadow": "*";
  /** Specifies the icons's color. */
  "--calcite-segmented-control-icon-color": "*";
}
}

export abstract class SegmentedControlItem extends LitElement {
  /**
   * When `true`, the component is checked.
   *
   * @default false
   */
  accessor checked: boolean;
  /** Specifies an icon to display at the end of the component. */
  accessor iconEnd: IconName | undefined;
  /**
   * When `true`, the icon will be flipped when the element direction is right-to-left (`"rtl"`).
   *
   * @default false
   */
  accessor iconFlipRtl: boolean;
  /** Specifies an icon to display at the start of the component. */
  accessor iconStart: IconName | undefined;
  /** The component's value. */
  accessor value: any | null;
}